def C (m k : ℕ) (v : ℝ) : ℝ :=
  if k = m then Real.sqrt (v ^ m)
  else if 0 < k ∧ k < m then
    Real.sqrt ((m : ℝ) ^ m / ((k : ℝ) ^ k * ((m - k : ℕ) : ℝ) ^ (m - k)) * v ^ k)
  else 0

def K (n : ℕ) (a x : ℝ) : ℂ :=
  ∫ t in (0 : ℝ)..1, ((family n x).map
    (fun q => (a : ℂ) + ((1-a^2)*t : ℝ)*q)).prod

def J (n : ℕ) (a x : ℝ) : ℂ :=
  ((family n x).card+1 : ℂ) * (∫ t in (0 : ℝ)..1,
    ((family n x).map (fun q => 1 - (a : ℂ)*t*q)).prod)

